import {dishes,experiences} from './data.js';
import {state,money,esc,icon,t,toast,save} from './state.js';
import * as C from './components.js';
import * as D from './dialogs.js';
import {translatePage,watchTranslations} from './i18n.js';
const app=document.querySelector('#app');
const isRoom=()=>location.pathname.startsWith('/room-service');
function render(){document.documentElement.lang=state.lang;document.title=isRoom()?'Room Service | Aurelis Grand Hotel':'Maison Aurelis | Aurelis Grand Hotel';app.innerHTML=C.Header()+(isRoom()?C.RoomService():`<main id="main">${C.Hero()}${C.RestaurantIntro()}${C.MenuCategories()}${C.Experiences()}${C.Reservations()}${C.Chef()}${C.WineCellar()}${C.Gallery()}${C.RoomServiceTeaser()}${C.PrivateEvents()}${C.Hotel()}${C.Testimonials()}${C.FinalCTA()}</main>`)+C.Footer();updateBadge();observe();translatePage();}
document.addEventListener('load',e=>{if(e.target.tagName==='IMG')e.target.classList.add('loaded')},true);
function observe(){document.querySelectorAll('img').forEach(im=>{if(im.complete&&im.naturalWidth)im.classList.add('loaded')});const obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal');obs.unobserve(e.target)}})},{threshold:.1});document.querySelectorAll('.section-heading,.intro-copy,.chef-section>div:last-child').forEach(el=>obs.observe(el));document.querySelectorAll('img[loading="lazy"]').forEach(img=>{img.style.background='#211e18';img.addEventListener('load',()=>img.style.background='',{once:true})});}
function updateBadge(){const count=state.cart.reduce((a,l)=>a+l.qty,0);document.querySelectorAll('.badge').forEach(e=>e.textContent=count);document.querySelectorAll('.mobile-count').forEach(e=>e.textContent=count?`(${count})`:'');}
function refreshMenu(){const grid=document.querySelector('#menu-grid');if(grid){grid.innerHTML=C.MenuResults();document.querySelectorAll('[data-action="category"]').forEach(b=>b.classList.toggle('selected',b.dataset.value===state.category));document.querySelectorAll('[data-action="filter"]').forEach(b=>b.classList.toggle('selected',b.dataset.value===state.filter));document.querySelector('.filter-favorites')?.classList.toggle('selected',state.favoritesOnly);}}
function add(id,qty=1,notes=''){const dish=dishes.find(d=>d.id===Number(id));if(!dish.available){toast('Este plato no está disponible hoy.');return;}const item=state.cart.find(l=>l.id===Number(id)&&l.notes===notes);if(item)item.qty=Math.min(20,item.qty+Number(qty));else state.cart.push({id:Number(id),qty:Number(qty),notes});save();updateBadge();toast(`${dish.name} · ${t('Añadido al pedido','Added to your order')}`);}
function goMenu(focus=false){D.closeModal();if(isRoom()){history.pushState({},'','/#carta');render();}document.querySelector('#carta')?.scrollIntoView();if(focus)document.querySelector('#dish-search')?.focus({preventScroll:true});}
const info={Contacto:['A su disposición','Concierge Aurelis · +51 900 000 000 — Demo. concierge@aurelis.example. Todos los datos de contacto son ficticios. Puede explorar las solicitudes desde nuestro concierge de demostración.'],'Preguntas frecuentes':['Antes de su visita','¿Cuál es el horario? Martes a domingo, 18:30–23:30. ¿Hay menú vegetal? Sí, Garden Degustation y opciones a la carta. ¿Puedo indicar alergias? Sí, en cada plato y reserva. ¿Puedo reservar para un grupo? Hasta 8 personas online; para grupos mayores, use Eventos privados. ¿Hay cobros reales? No: todos los flujos son simulados.'],'Privacidad':['Su privacidad','Esta demo guarda favoritos, carrito, pedidos y referencias de reservas en el almacenamiento local de su navegador. No cuenta con backend ni envía formularios. Puede eliminar esos datos mediante el botón inferior. Las fuentes se solicitan a Google Fonts. No introduzca información personal sensible.'],'Términos':['Una experiencia conceptual','Aurelis Grand Hotel, Maison Aurelis, sus personas, vinos, experiencias y testimonios son ficticios. Las fotografías son generadas por IA y representan el concepto; algunas se reutilizan para platos de la misma familia. No hay un hotel, servicio de entrega, reserva ni cobro real. Precios en soles, con 10% de servicio añadido en el pedido. Proyecto de demostración para portafolio.']};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el){if(e.target.classList.contains('modal-backdrop'))D.closeModal();return;}const {action,id,value,index,delta}=el.dataset;
switch(action){case'close':D.closeModal();break;case'lang':state.lang=state.lang==='es'?'en':'es';save();render();toast(t('Idioma: español','Language: English'));break;case'menu':D.modal(`<a class="brand" href="/">AURELIS<span>GRAND HOTEL</span></a>${[['inicio','Inicio'],['gastronomia','Gastronomía'],['carta','Carta'],['experiencias','Experiencias'],['reservas','Reservas'],['galeria','Galería'],['hotel','Hotel'],['contacto','Contacto']].map(([s,n])=>`<a href="/#${s}">${n}</a>`).join('')}<a href="/room-service">Room Service</a>`,'mobile-menu');break;case'search':goMenu(true);break;case'profile':D.Profile();break;case'cart':D.Cart();break;case'product':D.ProductModal(id);break;case'add':add(id);break;case'favorite':{const n=Number(id);state.favorites=state.favorites.includes(n)?state.favorites.filter(x=>x!==n):[...state.favorites,n];save();document.querySelectorAll(`[data-action="favorite"][data-id="${n}"]`).forEach(b=>{b.classList.toggle('active',state.favorites.includes(n));b.setAttribute('aria-pressed',state.favorites.includes(n))});if(state.favoritesOnly)refreshMenu();break;}case'category':state.category=value;refreshMenu();break;case'filter':state.filter=value;refreshMenu();break;case'favorites':state.favoritesOnly=!state.favoritesOnly;refreshMenu();break;case'show-favorites':state.favoritesOnly=true;state.category='Todos';state.filter='Todos';state.search='';goMenu();refreshMenu();break;case'reset-filters':state.category='Todos';state.filter='Todos';state.search='';state.favoritesOnly=false;document.querySelector('#dish-search').value='';refreshMenu();break;case'quantity':state.cart[index].qty=Math.max(1,Math.min(20,state.cart[index].qty+Number(delta)));save();D.Cart();updateBadge();break;case'remove':state.cart.splice(Number(index),1);save();D.Cart();updateBadge();break;case'edit-cart':D.ProductModal(state.cart[index].id,Number(index));break;case'browse':goMenu();break;case'checkout':if(state.cart.length)D.Checkout(true);break;case'delivery':case'payment':case'checkout-next':case'checkout-back':D.checkoutAction(action,value);break;case'confirm-order':D.confirmOrder();updateBadge();break;case'order-status':D.OrderStatus(id);break;case'reserve':D.ReservationsForm();break;case'reserve-slot':D.reserveSlot(value);break;case'experience':D.Experience(id);break;case'event':D.EventForm();break;case'breakfast':D.BreakfastForm();break;case'concierge':D.Concierge();break;case'special-request':D.modal(`<div class="eyebrow">CONCIERGE AURELIS</div><h2>Un pedido <em>especial.</em></h2><form id="special-form">${D.field('Nombre','name')}${D.field('Habitación o teléfono','contact')}<label>Su solicitud<textarea name="request" required maxlength="1000" placeholder="Cuéntenos cómo podemos ayudarle"></textarea></label><button class="btn full">Enviar solicitud simulada</button></form>`,'form-modal');break;case'concierge-chat':D.modal(`<div class="eyebrow">CONVERSACIÓN DE DEMOSTRACIÓN</div><h2>Concierge <em>Aurelis</em></h2><div id="chat-messages" aria-live="polite"><p>Bienvenido a Aurelis. Puedo orientarle sobre reservas, horarios y experiencias privadas.</p></div><form id="chat-form"><label>Mensaje<input name="message" maxlength="500" required placeholder="Escriba su consulta"></label><button class="btn full">Enviar</button></form><p class="fine-print">Asistente local con respuestas predefinidas. +51 900 000 000 — Demo</p>`,'form-modal');break;case'wine-filter':document.querySelector('#wine-list').innerHTML=C.WineRows(value);document.querySelectorAll('[data-action="wine-filter"]').forEach(b=>b.classList.toggle('selected',b===el));break;case'room-category':document.querySelector('#room-grid').innerHTML=C.RoomResults(value);document.querySelectorAll('[data-action="room-category"]').forEach(b=>b.classList.toggle('selected',b===el));break;case'gallery':D.modal(`<img src="/assets/${el.dataset.image}.webp" alt="${esc(el.dataset.title)}"><h3>${esc(el.dataset.title)}</h3>`,'gallery-modal');break;case'hotel':if(value==='Gastronomía'){D.closeModal();location.href='/#gastronomia';}else if(value==='Private Events')D.EventForm();else if(value==='Experiences'){D.closeModal();location.href='/#experiencias';}else if(value==='Concierge')D.Concierge();else D.modal(`<div class="eyebrow">EL UNIVERSO AURELIS</div><h2>${esc(value)}</h2><p>${{Hotel:'Una dirección ficticia concebida alrededor de la privacidad, la hospitalidad y el arte de disfrutar.',Suites:'Refugios amplios con materiales nobles, atención personalizada y gastronomía en la privacidad de su habitación.',Spa:'Rituales de bienestar, aromas sutiles y un tiempo reservado exclusivamente para usted.',Wellness:'Movimiento consciente, descanso y alimentación de temporada en perfecta armonía.',Rooftop:'La ciudad imaginaria a sus pies. Coctelería de autor y encuentros al atardecer.'}[value]||'Descubra una experiencia personalizada por Aurelis.'}</p><button class="btn" data-action="concierge">Consultar al concierge</button><p class="fine-print">Servicio conceptual del hotel ficticio.</p>`,'form-modal');break;case'info':{const [title,body]=info[value];D.modal(`<div class="eyebrow">AURELIS GRAND HOTEL</div><h2>${title}</h2><p>${body}</p>${value==='Privacidad'?'<button class="btn outline" data-action="clear-data">Eliminar mis datos locales</button>':''}`,'form-modal');break;}case'clear-data':state.cart=[];state.favorites=[];state.orders=[];state.reservations=[];save();sessionStorage.removeItem('aur-room');updateBadge();refreshMenu();D.closeModal();toast('Datos locales eliminados.');break;case'social':D.modal(`<div class="eyebrow">AURELIS / ${value.toUpperCase()}</div><h2>Un universo<br>por <em>compartir.</em></h2><p>Este proyecto no tiene una cuenta real en ${value}. Explore nuestra galería para descubrir la identidad visual de Aurelis.</p><button class="btn" data-action="visit-gallery">Explorar la galería</button>`,'form-modal');break;case'visit-gallery':D.closeModal();location.href='/#galeria';break;}
});
document.addEventListener('input',e=>{if(e.target.id==='dish-search'){state.search=e.target.value;refreshMenu();}if(e.target.name==='qty'&&e.target.closest('#product-form')){const d=dishes.find(x=>x.id===Number(e.target.form.dataset.id));document.querySelector('#product-total').textContent=money(d.price*Number(e.target.value||1));}if(e.target.id==='room-number')sessionStorage.setItem('aur-room',e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='pairing')document.querySelector('#pairing-result').innerHTML=C.Pairing(e.target.value);if(e.target.id==='delivery-timing'){const show=e.target.value==='schedule';document.querySelector('#schedule-fields').hidden=!show;document.querySelector('[name="schedule"]').required=show;}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));if(f.id==='product-form'){if(f.dataset.edit!==''){state.cart[Number(f.dataset.edit)]={id:Number(f.dataset.id),qty:Number(v.qty),notes:v.notes};save();updateBadge();D.Cart();}else{add(f.dataset.id,v.qty,v.notes);D.closeModal();}}if(f.id==='checkout-info')D.checkoutInfo(f);if(f.id==='reserve-availability')D.reserveAvailability(f);if(f.id==='reserve-details')D.reserveConfirm(f);if(['experience-form','event-form','special-form'].includes(f.id)){const kind=f.id==='experience-form'?experiences.find(x=>x.id===f.dataset.experience).name:f.id==='event-form'?v.event:'Pedido especial';const id='REQ-'+String(Date.now()).slice(-6);state.reservations.unshift({id,kind,date:v.date||D.today(),guests:v.guests||1});save();D.Success('Su solicitud está en buenas manos.',`${v.name}, hemos registrado su solicitud de ${kind.toLowerCase()}.`,id,true);}if(f.id==='breakfast-form'){if(new Date(`${v.date}T${v.time}`)<new Date()){toast('Seleccione una fecha y hora futura.');return;}sessionStorage.setItem('aur-room',v.room);add(v.breakfast,v.guests,`Desayuno programado · ${v.date} ${v.time} · Habitación ${v.room}`);state.cart.at(-1).schedule=`${v.date}T${v.time}`;save();D.Cart();}if(f.id==='chat-form'){const messages=document.querySelector('#chat-messages');const user=document.createElement('p');user.textContent='Usted: '+v.message;messages.append(user);const reply=document.createElement('p');reply.textContent=/hora/i.test(v.message)?'Concierge: Maison Aurelis sirve cenas de martes a domingo, de 18:30 a 23:30.':/reserva|mesa/i.test(v.message)?'Concierge: Puede consultar horarios y reservar desde «Reservar mesa». Para más de 8 invitados, use «Planificar un evento».':/alerg/i.test(v.message)?'Concierge: Indique sus alergias en el formulario de reserva y en las preferencias del plato. Nuestro equipo deberá revisar cada restricción.':'Concierge: Puede explorar experiencias privadas, programar un desayuno o crear un pedido. Esta conversación es una demostración con respuestas predefinidas.';messages.append(reply);f.reset();}});
document.addEventListener('keydown',e=>{const dialog=document.querySelector('.modal');if(!dialog)return;if(e.key==='Escape')D.closeModal();if(e.key==='Tab'){const focusable=[...dialog.querySelectorAll('a,button:not([disabled]),input,select,textarea')].filter(x=>x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const url=new URL(a.href);if(url.origin!==location.origin)return;if(url.pathname===location.pathname&&url.hash){D.closeModal();return;}if(url.pathname==='/'||url.pathname==='/room-service'){e.preventDefault();D.closeModal();history.pushState({},'',url);render();if(url.hash)setTimeout(()=>document.querySelector(url.hash)?.scrollIntoView(),0);else window.scrollTo(0,0);}});
window.addEventListener('scroll',()=>document.querySelector('#header')?.classList.toggle('scrolled',window.scrollY>30),{passive:true});window.addEventListener('popstate',render);watchTranslations();render();
